/**
 * Builds the question bank (#12): src/data/questions/t1.json ... t6.json.
 *
 * Each file = handwritten items (src/data/handwritten/tN.json) + generated items
 * (src/systems/generators) topped up to the targets below, with fixed seeds so the
 * output is identical every run. Also writes docs/QUESTION-SPOT-CHECK.md for the teacher.
 *
 *   npm run build:questions
 *
 * Do not edit src/data/questions/ by hand: edit the handwritten files or the generators,
 * then rebuild. tests/bank.test.ts fails if the committed bank is out of date.
 */
import { readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { FAMILIES, generateQuestions, supportedTypes } from '../src/systems/generators/index.ts';
import { hash } from '../src/systems/generators/core.ts';
import { createRng } from '../src/utils/rng.ts';
import {
  QUESTION_TYPES,
  type Choice,
  type Question,
  type QuestionType,
} from '../src/systems/questions.ts';

export const TARGET: Record<QuestionType, number> = { fluency: 20, application: 15, multistep: 15 };
export const TIERS = [1, 2, 3, 4, 5, 6];

const root = fileURLToPath(new URL('..', import.meta.url));

export function readHandwritten(tier: number): Question[] {
  return JSON.parse(
    readFileSync(join(root, `src/data/handwritten/t${tier}.json`), 'utf8'),
  ) as Question[];
}

/** Seed from the topic and type, so adding one topic does not reshuffle the others. */
const seedFor = (topic: string, type: QuestionType) => parseInt(hash(`${topic}|${type}`), 36);

export function buildTier(tier: number, handwritten: Question[]): Question[] {
  const out: Question[] = [];
  const stems = new Set(handwritten.flatMap((q) => [q.stem.id, q.stem.en]));
  for (const type of QUESTION_TYPES) {
    const hand = handwritten.filter((q) => q.type === type);
    out.push(...hand);
    const need = Math.max(0, TARGET[type] - hand.length);
    const pools = FAMILIES.filter(
      (f) => f.tier === tier && supportedTypes(f.topic).includes(type),
    ).map((f) => generateQuestions(f.topic, type, need + 5, seedFor(f.topic, type)));
    // Round-robin across topics so every generator topic is represented.
    let added = 0;
    for (let i = 0; added < need && pools.some((p) => i < p.length); i++) {
      for (const pool of pools) {
        const q = pool[i];
        if (!q || added >= need || stems.has(q.stem.id) || stems.has(q.stem.en)) continue;
        stems.add(q.stem.id);
        stems.add(q.stem.en);
        out.push(q);
        added++;
      }
    }
    if (added < need)
      throw new Error(`tier ${tier} ${type}: only ${added} of ${need} generated questions`);
  }
  return out;
}

export function buildBank(): Map<number, Question[]> {
  return new Map(TIERS.map((t) => [t, buildTier(t, readHandwritten(t))]));
}

export const serialize = (qs: Question[]) => JSON.stringify(qs, null, 2) + '\n';

const show = (c: Choice) => (typeof c === 'object' ? `${c.id} / ${c.en}` : String(c));

/** Every handwritten item + 5 generated per tier (well over the 10% the issue asks for). */
export function spotCheck(bank: Map<number, Question[]>): string {
  const total = [...bank.values()].reduce((n, qs) => n + qs.length, 0);
  const lines = [
    '# Question bank spot-check (#12)',
    '',
    'Generated by `npm run build:questions`. Do not edit by hand; record results in the table at the end.',
    '',
    `For the teacher: please check each item below. Tick it if the question, the marked answer (**bold**), the wrong choices and the explanation are correct and suitable for that Year, in both languages. Note anything to change. This covers every handwritten item and 5 generated items per Year, ${''}out of ${total} questions in total.`,
    '',
  ];
  for (const [tier, qs] of bank) {
    lines.push(`## Year ${tier}`, '');
    const hand = qs.filter((q) => q.source === 'handwritten');
    const gen = qs.filter((q) => q.source === 'generated');
    const rng = createRng(1000 + tier);
    const sample = [...gen]
      .sort((a, b) => a.id.localeCompare(b.id))
      .filter(() => rng() < 5 / gen.length);
    const picked = sample.length >= 5 ? sample.slice(0, 5) : gen.slice(0, 5);
    for (const q of [...hand, ...picked]) {
      const choices = q.choices
        .map((c, i) => (i === q.answerIndex ? `**${show(c)}**` : show(c)))
        .join(' · ');
      lines.push(
        `- [ ] \`${q.id}\` (${q.type}, ${q.source})`,
        `  - ID: ${q.stem.id}`,
        `  - EN: ${q.stem.en}`,
        `  - Choices: ${choices}`,
        `  - Explanation: ${q.explanation.id} / ${q.explanation.en}`,
      );
    }
    lines.push('');
  }
  lines.push(
    '## Results',
    '',
    '| Teacher | Date | Items checked | Problems found |',
    '|---|---|---|---|',
    '| Teacher review (name not recorded), reported by the project owner | 2026-11-07 | All items on this list | None |',
    '',
  );
  return lines.join('\n');
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  const bank = buildBank();
  for (const [tier, qs] of bank)
    writeFileSync(join(root, `src/data/questions/t${tier}.json`), serialize(qs));
  writeFileSync(join(root, 'docs/QUESTION-SPOT-CHECK.md'), spotCheck(bank));
  for (const [tier, qs] of bank) console.log(`Year ${tier}: ${qs.length} questions`);
}
